/* assets/i18n/cyclic-groups.js — the 'cyclicGroups' namespace: the title,
   eyebrow, heading and lede, the Cayley Table cross-link, the group-operation dropdown's accessible
   name, the Group panel's modulus and generator controls, the layer
   toggles, the arrow key and the color-by choice, the explanation panel and its hint lines, the color key, the
   necklace diagram texts, the explanation of why a group
   has no generator, and the ring PNG export for the Cyclic Groups tool.

   Translated into all thirty-one supported languages (quick task 261009-tgw),
   with English the source of truth: every non-English block holds the same
   keys in the same order as en, and i18n-check --coverage reports no
   cyclicGroups finding. The 34 keys added after that translation were
   translated by quick task 261011-cdw: the five iso.* keys (iso.lead,
   iso.additive, iso.multiplicative, iso.open, iso.supergroup) of the
   isomorphic-group selector, the *Math keys (cosetCountMath, nLabelMath,
   opLabelMath, nNoteMath, opAddMath, ..., notice.ruleMath), the templates
   whose math parameters are typeset as MathML, the formula.mulGroupOrder
   and formula.mulSubgroupOrder keys of the multiplicative order formulas,
   the formula.cosetCount, formula.mulCosetCount and formula.cosetCountIndex
   keys of the coset count formula, fact.cardinality, the five
   formulaToggle* labels, the three subOrder* strings of the generator
   prompt and tabTitle. The formula.* values and tabTitle are pure notation,
   identical in every left-to-right language (he, ar and ckb isolate them).
   Each placeholder of a *Math template is a MathML node supplied by the
   page and appears exactly once, never wrapped in isolates.
   The 105 keys added in English first after that (the full-screen window
   manager's fs* strings, the ring's right-click menu, the arrangement and
   element-expression controls, the Numerical panel's list controls and
   downloads, the auto-rotate ruler, the website-theme colour key and the
   rest) were translated by the catch-up pass of 2026-10-12. LaTeX, MathML,
   Unicode and ASCII stay Latin in every script, as format names.
   The 123 keys added in English first after that pass were translated
   by the catch-up pass of 2026-10-21 (zoomLabel, short labels and GCD/LCM
   follow each language's own terms where English would be identical or
   Latin is not allowed): subColorLabel and subColorTitle (the Numerical panel's
   checkbox colouring each member like its bead), and isoLockOpenGroup
   and isoLockOpenSub (the open padlock's tooltip, naming the isomorphism a
   double-click would lock), introAbout, introFullscreen and introEnter
   (the intro screen every visit opens on: what the tool does, why it is a
   full-screen application, and its button into the tool), introQrLabel
   and introQrCaption (the QR code of the page's own address beside the
   intro), and
   subExprSort (the Numerical panel's Generator expression following its
   Sort dropdown), subSortFollowCoupled (that Sort dropdown, merged across
   two rings, following their coupled expression sliders), subPathColours (the bottom panel's menu switch
   colouring the selected row and its inverse's like their paths), subPowerColours
   (its switch, with the paths drawn as powers of G, tinting each line's
   rows in that line's colour), subFormulaSize
   and subFormulaIndexShort (the bottom panel's Formula dropdown: the
   selected row's cardinality or index formula), subExprFollow (the Numerical panel's two expressions following the ring's
   expression slider), isoAddLeftTitle (the + at the ring's left edge,
   opening a new ring on the left), and subWidthLabel, subWidthNone,
   subAlign and subAlignTitle (the Numerical panel's dropdown lining up the
   columns: not at all, with blank space, or with the leading zeros of
   subPad), and ctxZoomIn and ctxZoomOut (the − and + of the window
   corner's zoom pill), and exprLockCouple and
   exprLockUncouple (the small padlock on the line between two locked
   rings, coupling their expression sliders), cosetLoop and cosetLoopTitle
   (the coset run's Loop toggle, replaying the cosets continuously),
   dirToggleCw and dirToggleCcw (the forward-direction button's name in
   each direction), combinePrompt (the line under the ring asking for the
   second element to combine with the first), and subRowGcd (a Numerical
   panel row's tooltip while the generating element is written as a
   power: the gcd of its exponent with the group's order, and the
   subgroup's order that follows), legendExprLabel (the inverse-pair
   colour key's menu writing its elements by number or as powers),
   showElementKey (the element colour key's switch in the window's bottom
   right corner, beside the arrow colour key's, which reuses showArrowKey),
   akeyPick (a bar of the arrow colour key, clicked for its path's colour
   picker), akeyShowBackward (the key's eye bringing the backwards path
   back), zoomLabel and zoomWheel (the corner's zoom slider and its
   switch letting the scroll wheel zoom the ring), zoomReset (the zoom
   pill's percentage, which sets the zoom back to 100%), akeyOneLine (the
   key's switch drawing both paths on one line), akeyPairMode,
   akeyShowPower, akeyHidePower, akeyPowerExp, akeyPowerSide, akeyAddLine
   and akeyDropLine (that line in one colour from the subgroup cardinality
   key, with further lines, added with a + and removed again, for the
   powers picked for them, each with its eye, power and side), and
   akeyPath and akeyOrderSame (those lines'
   texts: the path of an element and its inverse, written out), and
   subPanelFollow (the subgroup dropdown's entry keeping the subgroup
   picked in the Subgroups generated by each element panel), and splitOpen
   and splitClose (the chevron button's tooltip, opening or closing that
   panel; they replace splitView), and exprGensAdd and exprGensMul (plural
   entries: the expression slider's tooltip, naming it and counting the generators,
   φ(n) or φ(φ(n))), and akeyPathGeneral (a
   one-colour line's text beside a locked pane, in powers of G), and
   akeyTipGroup (the group column's head of the hover tables there: a
   one-colour line's, giving its pair by value per ring), and subGcd,
   subGcdTitle, subGcdDivider, subGcdHideDividers, subGcdShowDividers,
   subGcdCollapse and subGcdExpand
   (the switch beside the subgroups' sort grouping the rows by the gcd of
   their exponent with the group's cardinality, the divider heading each
   group, the rows' right-click entries hiding or showing those
   dividers, and a divider's tooltip folding its group's rows away or
   unfolding them), and subFormulaRowLabel and subFormulaRowLabelShort
   (the subgroup list's choice of formula shown in the selected row), and
   formula.subgroupOrderLog and formula.subgroupIndexLog (the additive row
   formulas that, the formula slider not at its simplest, find h as
   log_g h), and
   formula.mulSubgroupOrderSteps, formula.mulSubgroupIndexSteps and
   formula.mulCosetCountSteps (the multiplicative row formulas writing
   log_g h out as log_g g^q, then q), formulaLevelLabel,
   opKindEc (the group-operation pyramid's top corner, elliptic-curve point
   addition, beside opKindAdd and opKindMul),
   formulaLevelNone, formulaLevelCompact and formulaLevelComplete (the formula complexity
   slider in the ring's bottom bar and its three stops' tooltips; the stops
   also set how the locked rings' a ∗ b columns are worked), barFormulas,
   barLcmRow, barLcmMain, barGcd, barLcm and barShow (the
   bottom bar's per-group formula menu, barShow its one choice on a curve), colorByDistinct and legendHeadingDistinct (the Element
   colours choice giving every element a colour of its own, and its key) and formula.subgroupOrderLcm,
   formula.subgroupIndexLcm, formula.subgroupOrderLogLcm,
   formula.subgroupIndexLogLcm, formula.mulOrderLcm and formula.mulIndexLcm
   (those forms: |⟨h⟩| = lcm(|G|, q) / q, [G : ⟨h⟩] = |G| · q / lcm(|G|, q)),
   and plotDock and plotFloat (the curve plot's button docking it in the
   strip at the bottom of the Ring window, and floating it over the ring
   again), and plotHalosPath and plotHalosAb (the curve plot's menu choosing
   which points it rings: G and its inverse in their paths' colours, or the
   elements a and b being combined), and exprHoverSignOn, exprHoverSignOff,
   exprHoverSignOnEc, exprHoverSignOffEc, exprHoverSignExpOn and
   exprHoverSignExpOff (the On hover slider's own ± and g^± switches,
   signing what Reveal on hover shows), and nLabelTitle (the tooltip of
   the % alone naming the modulus in the Ring window's top row), and
   arrangeNotApplicable and arrangeNotApplicableTitle (the padlocked
   Generator dropdown while a group of units, or a group with no
   generator, is arranged Sequential).
   The 122 keys added in English first after the pass of 2026-10-21
   (the scalar combination aᵏ, the elliptic curves and their plot over
   the reals, the preferred directions, the flip and the lock slider, the
   polygon of rotations, the On hover expression slider, and the keys
   named above from nLabelTitle on) were translated into all thirty
   languages by the catch-up pass of 2026-10-29; kP and Pᵏ stay Latin in
   every script, as notation.
   Added in English first since that pass, for the next catch-up
   translation: identityE (the tooltip of the E in E = 0, E = 1 or E = 𝒪
   after the pyramid, its {einheit} an <i>Einheit</i> node supplied by
   the page), and cayleyShort, cayleyTitle, cayleyTitlePairs, cayleyShow,
   cayleyTask, cayleyMerge and cayleySplit (the Cayley table's window, its
   task in the bottom bar and the switch merging two locked rings' tables
   into one of linked pairs), and cayleyModeHover and cayleyModeReveal
   (the switch between the table's two modes), and exprTie and exprUntie
   (the lock tying the No hover and On hover sliders, which replaced the
   menu's Disable reveal on hover, menuRevealOff), and ecColCurve and
   ecSortBy (the example curves' table: its curve column, its columns' sort
   tooltip), idPickLabel (the dropdown after E =), and subExprFollowTitle
   (the bottom panel's Follow expression slider button), and formulaToGcd
   and formulaToLcm (the main view formula's right-click switch between its
   GCD and LCM forms), and dhMenu, dhTitle, dhClose, dhAlice, dhPublic,
   dhBob, dhSecretA, dhSecretB, dhNoteSub, dhNoteIdentity, dhStep0 to
   dhStep6, dhKey, dhBack and dhNew (the ring menu's Diffie–Hellman
   exchange worked with G as g, and its window), and swapIsoMenu (the ring
   menu's Swap for an isomorphic group on a cyclic group), and genInWhole and
   genInProper (the tip on the subgroup row's ∈, ⟨h⟩ the whole group or not), and
   genSwitch (the subgroup row's on/off switch), genBeads and genBeadsTitle
   (its Follow bead clicks button, picking G by a click on a bead) and
   genBeadsEc and genBeadsEcTitle (the same button on a curve, where a point
   in the plot counts too), and cosetExit (Step's place once a coset run has no
   step left, ending the run) and subCosetsExplore (the bottom panel's menu
   item starting a run on a row). Every other language shows the English value through
   NT.i18n's fallback meanwhile.

   Classic script, IIFE, "use strict" — its only statement is
   NT.i18n.register(...). legendSubgroups and subRowGcd are plural entries in each
   language's own CLDR category shape ({ one, other } in English);
   every other key is plain text. The notice.* values are whole sentences
   whose {group}, {count}, {longest}, {factors} and {n} placeholders are
   <code> nodes supplied by the page script, rendered via translateInto,
   never as markup strings. Notation (ℤ/nℤ, (ℤ/nℤ)*, ℤ/2ℤ × ℤ/4ℤ) and numerals
   are written the same way in every language; Hebrew, Arabic and Sorani
   Kurdish wrap formulas and notation in U+2066…U+2069 isolates, written as
   \u2066 / \u2069 escapes. Additive Groups and
   Multiplicative Groups live in the shared `common` namespace
   (assets/i18n/site.js), never duplicated here. Must load after
   assets/nt-i18n.js and assets/i18n/site.js, before the page's own inline
   <script>.
*/
