      formulaLevelComplete: 'Complete',
      'formula.subgroupOrderLog': '|⟨{h}⟩| = |{group}| / gcd(|{group}|, log_{g}({h})) = {n} / gcd({n}, log_{g}({g}^{q})) = {n} / gcd({n}, {q}) = {n} / {d} = {k}',
      'formula.subgroupIndexLog': '[{group} : ⟨{h}⟩] = gcd(|{group}|, log_{g}({h})) = gcd({n}, log_{g}({g}^{q})) = gcd({n}, {q}) = {d}',
      'formula.mulSubgroupOrderSteps': '|⟨{h}⟩| = |{group}| / gcd(|{group}|, log_{g}({h})) = φ({n}) / gcd(φ({n}), log_{g}({g}^{q})) = {k} / gcd({k}, {q}) = {k} / {d} = {m}',
      'formula.mulSubgroupIndexSteps': '[{group} : ⟨{h}⟩] = gcd(|{group}|, log_{g}({h})) = gcd(φ({n}), log_{g}({g}^{q})) = gcd({k}, {q}) = {d}',
      'formula.subgroupOrderLcm': '|⟨{h}⟩| = lcm(|{group}|, {q}) / {q} = lcm({n}, {q}) / {q} = {l} / {q} = {m}',
      'formula.subgroupIndexLcm': '[{group} : ⟨{h}⟩] = |{group}| · {q} / lcm(|{group}|, {q}) = {n} · {q} / lcm({n}, {q}) = {p} / {l} = {d}',
      'formula.subgroupOrderLogLcm': '|⟨{h}⟩| = lcm(|{group}|, log_{g}({h})) / log_{g}({h}) = lcm({n}, log_{g}({g}^{q})) / log_{g}({g}^{q}) = lcm({n}, {q}) / {q} = {l} / {q} = {m}',
      'formula.subgroupIndexLogLcm': '[{group} : ⟨{h}⟩] = |{group}| · log_{g}({h}) / lcm(|{group}|, log_{g}({h})) = {n} · log_{g}({g}^{q}) / lcm({n}, log_{g}({g}^{q})) = {n} · {q} / lcm({n}, {q}) = {p} / {l} = {d}',
      'formula.mulOrderLcm': '|⟨{h}⟩| = lcm(|{group}|, log_{g}({h})) / log_{g}({h}) = lcm(φ({n}), log_{g}({g}^{q})) / log_{g}({g}^{q}) = lcm({k}, {q}) / {q} = {l} / {q} = {m}',
      'formula.mulIndexLcm': '[{group} : ⟨{h}⟩] = |{group}| · log_{g}({h}) / lcm(|{group}|, log_{g}({h})) = φ({n}) · log_{g}({g}^{q}) / lcm(φ({n}), log_{g}({g}^{q})) = {k} · {q} / lcm({k}, {q}) = {p} / {l} = {d}',
      'formula.mulCosetCountSteps': '|{group}| / |⟨{h}⟩| = gcd(|{group}|, log_{g}({h})) = gcd(φ({n}), log_{g}({g}^{q})) = gcd({k}, {q}) = {d}',
