      introAbout: 'Groupes cycliques transforme un groupe en un cercle de perles, une perle par élément. Choisissez un module et une opération — l’addition modulo n, ou la multiplication des inversibles modulo n — puis un élément : ses cordes font le tour du cercle, et lorsqu’elles atteignent toutes les perles, cet élément engendre le groupe entier, ce qui rend le groupe cyclique. Le cercle remplit l’écran, avec les commandes du groupe au-dessus. La liste numérique montre le sous-groupe engendré par chaque élément, et un groupe isomorphe peut être ouvert à côté du cercle et y être verrouillé avec le cadenas, afin que les deux tournent, se colorent et se mettent en évidence ensemble.',
      introFullscreen: 'Comme cet outil a tant de commandes, c’est en réalité une application plein écran. Il s’utilise au mieux en plein écran, et l’en-tête habituel du site est masqué dans tous les cas. Pour revenir au reste du site, utilisez les boutons Précédent et Suivant de votre navigateur au lieu de l’en-tête. Amusez-vous bien !',
