      isoLockOpenSub: 'Kliknij dwukrotnie, aby zablokować grupy razem przez izomorfizm podgrupy z grupą',
      introAbout: 'Grupy cykliczne zamieniają grupę w okrąg koralików, po jednym koraliku na każdy element. Wybierz moduł i działanie — dodawanie modulo n albo mnożenie elementów odwracalnych modulo n — a potem wybierz element: jego cięciwy obiegają okrąg, a gdy dotrą do każdego koralika, ten element generuje całą grupę, co czyni grupę cykliczną. Okrąg wypełnia ekran, a nad nim są elementy sterujące grupy. Lista liczbowa pokazuje podgrupę generowaną przez każdy element, a obok okręgu można otworzyć grupę izomorficzną i zablokować ją z nim kłódką, tak aby obie obracały się, kolorowały i podświetlały jako jedna całość.',
      introFullscreen: 'Ponieważ to narzędzie ma tak wiele elementów sterujących, jest właściwie aplikacją pełnoekranową. Najlepiej używać go na pełnym ekranie, a zwykły nagłówek strony i tak jest ukryty. Aby wrócić do reszty strony, użyj przycisków Wstecz i Dalej przeglądarki zamiast nagłówka. Miłej zabawy!',
