      introAbout: 'Grupos cíclicos transforma um grupo em um círculo de contas, uma conta para cada elemento. Escolha um módulo e uma operação — adição módulo n ou multiplicação das unidades módulo n — e depois escolha um elemento: suas cordas percorrem o círculo e, quando alcançam todas as contas, esse elemento gera o grupo inteiro, o que torna o grupo cíclico. O círculo ocupa a tela, com os controles do grupo acima dele. A lista numérica mostra o subgrupo que cada elemento gera, e um grupo isomorfo pode ser aberto ao lado do círculo e travado a ele com o cadeado, para que os dois girem, se colorem e se destaquem como um só.',
