      introAbout: 'Grupuri ciclice transformă un grup într-un cerc de mărgele, câte o mărgea pentru fiecare element. Alege un modul și o operație — adunarea modulo n sau înmulțirea unităților modulo n — apoi alege un element: coardele lui merg în jurul cercului, iar când ajung la fiecare mărgea, acel element generează întregul grup, ceea ce face grupul ciclic. Cercul umple ecranul, cu controalele grupului deasupra lui. Lista numerică arată subgrupul generat de fiecare element, iar un grup izomorf poate fi deschis lângă cerc și blocat împreună cu el prin lacăt, astfel încât cele două se rotesc, se colorează și se evidențiază ca unul singur.',
      introFullscreen: 'Pentru că are atât de multe controale, acest instrument este de fapt o aplicație pe ecran complet. Se folosește cel mai bine pe ecran complet, iar antetul obișnuit al site-ului este ascuns oricum. Ca să te întorci la restul site-ului, folosește butoanele Înapoi și Înainte ale browserului în locul antetului. Distracție plăcută!',
