      isoLockOpenSub: 'Dupla kattintással összezárod a csoportokat a részcsoport–csoport izomorfizmuson keresztül',
      introAbout: 'A Ciklikus csoportok egy csoportot gyöngyökből álló körré alakít, minden elemnek egy gyöngy jut. Válassz egy modulust és egy műveletet — összeadást modulo n, vagy a modulo n egységek szorzását —, majd válassz egy elemet: a húrjai körbejárják a kört, és ha minden gyöngyöt elérnek, az az elem az egész csoportot generálja, ettől ciklikus a csoport. A kör kitölti a képernyőt, felette a csoport vezérlőivel. A Numerikus lista megmutatja az egyes elemek által generált részcsoportot, és egy izomorf csoport megnyitható a kör mellett, majd a lakattal hozzá zárható, így a kettő együtt forog, színeződik és emelődik ki.',
      introFullscreen: 'Mivel ennek az eszköznek nagyon sok vezérlője van, valójában teljes képernyős alkalmazás. Teljes képernyőn a legjobb használni, és a webhely szokásos fejléce mindenképp rejtve marad. A webhely többi részére a böngésző Vissza és Előre gombjaival juthatsz vissza a fejléc helyett. Jó szórakozást!',
