      isoLockOpenGroup: 'Veic dubultklikšķi, lai sasaistītu grupas ar to grupas–grupas izomorfismu',
      isoLockOpenSub: 'Veic dubultklikšķi, lai sasaistītu grupas ar apakšgrupas–grupas izomorfismu',
      introAbout: 'Cikliskās grupas pārvērš grupu par pērļu apli — katram elementam viena pērle. Izvēlies moduli un darbību — saskaitīšanu pēc moduļa n vai vienību reizināšanu pēc moduļa n —, tad izvēlies elementu: tā hordas iet apkārt aplim, un, kad tās sasniedz katru pērli, šis elements ģenerē visu grupu, un tas padara grupu par ciklisku. Aplis aizpilda ekrānu, un grupas vadīklas ir virs tā. Skaitliskais saraksts rāda apakšgrupu, ko ģenerē katrs elements, un izomorfu grupu var atvērt blakus aplim un sasaistīt ar to ar piekaramo slēdzeni, lai abas grieztos, krāsotos un izceltos kā viena.',
      introFullscreen: 'Tā kā šim rīkam ir tik daudz vadīklu, tas patiesībā ir pilnekrāna lietotne. To vislabāk lietot pilnekrāna režīmā, un vietnes parastā galvene jebkurā gadījumā ir paslēpta. Lai atgrieztos pārējā vietnē, galvenes vietā izmanto pārlūka pogas Atpakaļ un Uz priekšu. Lai jautri!',
      introEnter: 'Atvērt Cikliskās grupas pilnekrāna režīmā',
      introQrLabel: 'QR kods šīs lapas adresei',
      introQrCaption: 'Noskenē, lai atvērtu šo lapu tālrunī',
