      isoLockOpenGroup: 'Дважды щёлкни, чтобы связать группы их изоморфизмом группы на группу',
      isoLockOpenSub: 'Дважды щёлкни, чтобы связать группы изоморфизмом подгруппы на группу',
      introAbout: '«Циклические группы» превращают группу в окружность из бусин — по одной бусине на каждый элемент. Выбери модуль и операцию — сложение по модулю n или умножение обратимых элементов по модулю n, — затем выбери элемент: его хорды обходят окружность, и если они достигают каждой бусины, этот элемент порождает всю группу, а значит, группа циклическая. Окружность занимает весь экран, а над ней находятся элементы управления группой. Числовой список показывает подгруппу, порождаемую каждым элементом, а изоморфную группу можно открыть рядом с окружностью и связать с ней замком, чтобы обе вращались, окрашивались и подсвечивались как одна.',
      introFullscreen: 'Элементов управления у этого инструмента так много, что по сути это полноэкранное приложение. Лучше всего пользоваться им в полноэкранном режиме, а обычный заголовок сайта скрыт в любом случае. Чтобы вернуться к остальному сайту, используй кнопки браузера «Назад» и «Вперёд» вместо заголовка. Удачи!',
