      isoAskLockGroup: 'Βρέθηκε ισομορφισμός ομάδας με ομάδα! Κλείδωμα των ομάδων;',
      isoAskLockSub: 'Βρέθηκε ισομορφισμός υποομάδας με ομάδα! Κλείδωμα των ομάδων;',
      isoLockOpenGroup: 'Διπλό κλικ για κλείδωμα των ομάδων μέσω του ισομορφισμού ομάδας με ομάδα',
      isoLockOpenSub: 'Διπλό κλικ για κλείδωμα των ομάδων μέσω του ισομορφισμού υποομάδας με ομάδα',
      introAbout: 'Οι Κυκλικές ομάδες μετατρέπουν μια ομάδα σε δακτύλιο από χάντρες, μία χάντρα για κάθε στοιχείο. Διάλεξε ένα μέτρο και μια πράξη — πρόσθεση mod n ή πολλαπλασιασμό των αντιστρέψιμων στοιχείων mod n — και μετά διάλεξε ένα στοιχείο: οι χορδές του κάνουν τον γύρο του δακτυλίου, και όταν φτάνουν σε κάθε χάντρα, το στοιχείο αυτό παράγει ολόκληρη την ομάδα, κάτι που την κάνει κυκλική. Ο δακτύλιος γεμίζει την οθόνη, με τα χειριστήρια της ομάδας από πάνω του. Η Αριθμητική λίστα δείχνει την υποομάδα που παράγει κάθε στοιχείο, και μια ισομορφική ομάδα μπορεί να ανοίξει δίπλα στον δακτύλιο και να κλειδωθεί μαζί του με το λουκέτο, ώστε οι δύο να περιστρέφονται, να χρωματίζονται και να επισημαίνονται ως μία.',
      introFullscreen: 'Επειδή αυτό το εργαλείο έχει τόσα πολλά χειριστήρια, στην ουσία είναι εφαρμογή πλήρους οθόνης. Χρησιμοποιείται καλύτερα σε πλήρη οθόνη, και η συνηθισμένη κεφαλίδα του ιστότοπου είναι κρυμμένη σε κάθε περίπτωση. Για να επιστρέψεις στον υπόλοιπο ιστότοπο, χρησιμοποίησε τα κουμπιά Πίσω και Εμπρός του προγράμματος περιήγησης αντί για την κεφαλίδα. Καλή διασκέδαση!',
      introEnter: 'Άνοιγμα των Κυκλικών ομάδων σε πλήρη οθόνη',
      introQrLabel: 'Κωδικός QR για τη διεύθυνση αυτής της σελίδας',
