      isoLockOpenSub: 'לחיצה כפולה לנעילת החבורות דרך האיזומורפיזם מתת-חבורה לחבורה',
      introAbout: 'חבורות ציקליות הופך חבורה לטבעת של חרוזים, חרוז אחד לכל איבר. בחרו מודולוס ופעולה — חיבור מודולו n, או כפל של האיברים ההפיכים מודולו n — ואז בחרו איבר: המיתרים שלו הולכים סביב הטבעת, וכשהם מגיעים לכל חרוז, האיבר הזה יוצר את החבורה כולה, וזה מה שהופך את החבורה לציקלית. הטבעת ממלאת את המסך, ופקדי החבורה מעליה. הרשימה המספרית מציגה את תת-החבורה שכל איבר יוצר, ואפשר לפתוח חבורה איזומורפית לצד הטבעת ולנעול אותה אליה עם המנעול, כך ששתיהן מסתובבות, נצבעות ומודגשות כאחת.',
      introFullscreen: 'מכיוון שיש בכלי הזה כל כך הרבה פקדים, הוא למעשה יישום למסך מלא. הכי טוב להשתמש בו במסך מלא, והכותרת הרגילה של האתר מוסתרת בכל מקרה. כדי לחזור לשאר האתר, השתמשו בכפתורי הקודם והבא של הדפדפן במקום בכותרת. תהנו!',
