      isoAskLockGroup: 'تم العثور على تماثل من زمرة إلى زمرة! هل تريد قفل الزمرتين معا؟',
      isoAskLockSub: 'تم العثور على تماثل من زمرة جزئية إلى زمرة! هل تريد قفل الزمرتين معا؟',
      isoLockOpenGroup: 'انقر نقرا مزدوجا لقفل الزمرتين عبر تماثلهما من زمرة إلى زمرة',
      isoLockOpenSub: 'انقر نقرا مزدوجا لقفل الزمرتين عبر التماثل من زمرة جزئية إلى زمرة',
      introAbout: 'تحول أداة الزمر الدورية الزمرة إلى حلقة من الخرز، خرزة لكل عنصر. اختر مقياسا وعملية — الجمع بمقياس n، أو ضرب الوحدات بمقياس n — ثم اختر عنصرا: تدور أوتاره حول الحلقة، وعندما تصل إلى كل خرزة يكون ذلك العنصر مولدا للزمرة كلها، وهذا ما يجعل الزمرة دورية. تملأ الحلقة الشاشة وفوقها أدوات التحكم في الزمرة. تعرض القائمة العددية الزمرة الجزئية التي يولدها كل عنصر، ويمكن فتح زمرة متماثلة بجانب الحلقة وقفلها معها بالقفل، فتدوران وتتلونان وتبرزان معا كأنهما واحدة.',
      introFullscreen: 'لأن في هذه الأداة أدوات تحكم كثيرة جدا، فهي في الحقيقة تطبيق بملء الشاشة. من الأفضل استخدامها بملء الشاشة، ورأس الموقع المعتاد مخفي في الحالتين. للعودة إلى بقية الموقع، استخدم زري الرجوع والتقدم في متصفحك بدلا من الرأس. استمتع!',
      introEnter: 'فتح الزمر الدورية بملء الشاشة',
