      introAbout: 'Grupet ciklike e kthen një grup në një unazë rruazash, një rruazë për çdo element. Zgjidhni një modul dhe një veprim — mbledhje modulo n, ose shumëzim të njësive modulo n — pastaj zgjidhni një element: kordat e tij ecin rreth unazës, dhe kur arrijnë çdo rruazë, ai element gjeneron të gjithë grupin, gjë që e bën grupin ciklik. Unaza mbush ekranin, me kontrollet e grupit sipër saj. Lista numerike tregon nëngrupin që gjeneron çdo element, dhe një grup izomorf mund të hapet pranë unazës dhe të lidhet me të me drynin, që të dyja të rrotullohen, të ngjyrosen dhe të theksohen si një.',
