      isoLockOpenSub: 'Bofya mara mbili ili kufunga makundi pamoja kupitia isomofizimu ya kundi dogo kwa kundi',
      introAbout: 'Makundi ya mzunguko hugeuza kundi kuwa pete ya shanga, shanga moja kwa kila kipengele. Chagua moduli na operesheni — kujumlisha modulo n, au kuzidisha vipashio modulo n — kisha chagua kipengele: kamba zake hutembea kuzunguka pete, na zinapofikia kila shanga, kipengele hicho huzalisha kundi zima, jambo linalofanya kundi liwe la mzunguko. Pete hujaza skrini, na vidhibiti vya kundi viko juu yake. Orodha ya Namba huonyesha kundi dogo ambalo kila kipengele huzalisha, na kundi isomofiki linaweza kufunguliwa kando ya pete na kufungwa nayo kwa kufuli, ili yote mawili yazunguke, yapakwe rangi na kuangaziwa kama kitu kimoja.',
      introFullscreen: 'Kwa kuwa zana hii ina vidhibiti vingi sana, kwa kweli ni programu ya skrini nzima. Inatumika vizuri zaidi kwenye skrini nzima, na kichwa cha kawaida cha tovuti kimefichwa kwa vyovyote vile. Ili kurudi kwenye sehemu nyingine za tovuti, tumia vitufe vya Nyuma na Mbele vya kivinjari chako badala ya kichwa. Furahia!',
