      introAbout: '순환군은 군을 구슬 고리로 바꿉니다. 원소 하나에 구슬 하나입니다. 법과 연산(법 n에 대한 덧셈, 또는 법 n에 대한 단원의 곱셈)을 고른 다음 원소를 하나 고르세요. 그 원소의 현이 고리를 따라 돌고, 모든 구슬에 이르면 그 원소가 군 전체를 생성하며, 그래서 그 군은 순환군이 됩니다. 고리는 화면을 가득 채우고 그 위에 군의 컨트롤이 있습니다. 숫자 목록은 각 원소가 생성하는 부분군을 보여 주며, 동형인 군을 고리 옆에 열어 자물쇠로 잠그면 두 고리가 함께 회전하고, 색이 칠해지고, 강조됩니다.',
      introFullscreen: '이 도구에는 컨트롤이 아주 많아서 사실상 전체 화면 애플리케이션입니다. 전체 화면에서 쓰는 것이 가장 좋으며, 어느 쪽이든 웹사이트의 평소 헤더는 숨겨집니다. 웹사이트의 다른 페이지로 돌아가려면 헤더 대신 브라우저의 뒤로 및 앞으로 버튼을 사용하세요. 즐겁게 사용하세요!',
