      introAbout: 'Grûpên çerxî grûpekê dike xelekeke moriyan, ji bo her hêmanê moriyek. Modulek û operasyonek hilbijêre — lêzêdekirin modulo n, an lêkdana yekeyan modulo n — paşê hêmanekê hilbijêre: watarên wê li dora xelekê digerin, û gava ku digihîjin her moriyê, ew hêman tevahiya grûpê çêdike, û ev yek grûpê çerxî dike. Xelek ekranê tijî dike û kontrolên grûpê li jora wê ne. Lîsteya Hejmarî binegrûpa ku her hêman çêdike nîşan dide, û grûpeke îzomorf dikare li kêleka xelekê were vekirin û bi qeflê pê ve were girêdan, da ku her du wekî yek bizivirin, reng bibin û ronî bibin.',
