      isoLockOpenSub: 'دوو کرتە بکە بۆ قوفڵکردنی گرووپەکان لە ڕێگەی ئیزۆمۆرفیزمی ژێرگرووپ بۆ گرووپەوە',
      introAbout: 'گرووپە خولییەکان گرووپێک دەکات بە ئەڵقەیەک لە مووروو، مووروویەک بۆ ھەر توخمێک. مۆدیولێک و کردارێک ھەڵبژێرە — کۆکردنەوە بە مۆدیولی n، یان لێکدانی یەکەکان بە مۆدیولی n — پاشان توخمێک ھەڵبژێرە: ھێڵە بڕەکانی بە دەوری ئەڵقەکەدا دەڕۆن، و کاتێک دەگەنە ھەموو موورووەکان ئەو توخمە ھەموو گرووپەکە بەرھەم دەھێنێت، ئەمەش وا لە گرووپەکە دەکات خولی بێت. ئەڵقەکە شاشەکە پڕ دەکات و کۆنترۆڵەکانی گرووپ لە سەرەوەیەتی. لیستی ژمارەیی ئەو ژێرگرووپە پیشان دەدات کە ھەر توخمێک بەرھەمی دەھێنێت، و دەتوانرێت گرووپێکی ئیزۆمۆرف لە تەنیشت ئەڵقەکەوە بکرێتەوە و بە قوفڵەکە پێیەوە ببەسترێت، بۆ ئەوەی ھەردووکیان وەک یەک بسووڕێنەوە، ڕەنگ بکرێن و دیار بکرێن.',
      introFullscreen: 'لەبەر ئەوەی ئەم ئامرازە ئەوەندە زۆر کۆنترۆڵی ھەیە، لە ڕاستیدا بەرنامەیەکی پڕشاشەیە. باشترە بە پڕشاشە بەکاری بھێنیت، و سەردێڕی ئاسایی ماڵپەڕەکە لە ھەردوو حاڵەتدا شاراوەیە. بۆ گەڕانەوە بۆ بەشەکانی تری ماڵپەڕەکە، لە جیاتی سەردێڕەکە دوگمەکانی دواوە و پێشەوەی وێبگەڕەکەت بەکار بھێنە. کات خۆش!',
