      isoAskLockGroup: 'समूहात् समूहं प्रति समरूपता लब्धा! समूहौ बध्नातु?',
      isoAskLockSub: 'उपसमूहात् समूहं प्रति समरूपता लब्धा! समूहौ बध्नातु?',
      isoLockOpenGroup: 'समूहौ तयोः समूहात् समूहं प्रति समरूपतया बद्धुं द्विवारं नुदतु',
      isoLockOpenSub: 'समूहौ उपसमूहात् समूहं प्रति समरूपतया बद्धुं द्विवारं नुदतु',
      introAbout: 'चक्रीयसमूहाः इति साधनं समूहं मणीनां वलये परिवर्तयति, प्रत्येकस्य अवयवस्य एकः मणिः। एकं मापाङ्कम् एकां सङ्क्रियां च चिनोतु — n मापाङ्केन योगः, अथवा n मापाङ्केन एककानां गुणनम् — ततः एकम् अवयवं चिनोतु: तस्य जीवाः वलयं परितः गच्छन्ति, यदा च ताः सर्वान् मणीन् प्राप्नुवन्ति तदा सः अवयवः सम्पूर्णं समूहं जनयति, तेन च समूहः चक्रीयः भवति। वलयं पटलं पूरयति, तस्य उपरि समूहस्य नियन्त्रणानि सन्ति। सङ्ख्यात्मकसूची प्रत्येकेन अवयवेन जनितम् उपसमूहं दर्शयति, समरूपः समूहः च वलयस्य पार्श्वे उद्घाटयितुं तालेन तेन सह बद्धुं च शक्यते, येन उभौ एकवत् भ्रमतः, वर्ण्येते, उद्भास्येते च।',
      introFullscreen: 'अस्मिन् साधने अतीव बहूनि नियन्त्रणानि सन्ति, अतः वस्तुतः इदं पूर्णपटलानुप्रयोगः अस्ति। पूर्णपटले एव अस्य उपयोगः श्रेष्ठः, जालस्थलस्य सामान्यशीर्षकं तु उभयथा अपि गुप्तम् अस्ति। जालस्थलस्य शेषभागं प्रति प्रत्यागन्तुं शीर्षकस्य स्थाने स्वजालविचरकस्य पश्चगमनाग्रगमनकुञ्जिके उपयुङ्क्ताम्। आनन्दम् अनुभवतु!',
      introEnter: 'चक्रीयसमूहान् पूर्णपटले उद्घाटयतु',
      introQrLabel: 'अस्य पृष्ठस्य जालसङ्केतस्य QR-कूटम्',
